public static void decompileSaveOpenedOnly() {
    if (BytecodeViewer.promptIfNoLoadedClasses())
        return;
    if (!BytecodeViewer.isActiveResourceClass()) {
        BytecodeViewer.showMessage(TranslatedStrings.FIRST_VIEW_A_CLASS.toString());
        return;
    }
    Thread decompileThread = new Thread(() -> {
        if (!BytecodeViewer.autoCompileSuccessful())
            return;
        final ClassNode cn = BytecodeViewer.getCurrentlyOpenedClassNode();
        JFileChooser fc = new FileChooser(Configuration.getLastSaveDirectory(), "Select Java Files", "Java Source Files", "java");
        int returnVal = fc.showSaveDialog(BytecodeViewer.viewer);
        if (returnVal == JFileChooser.APPROVE_OPTION) {
            Configuration.setLastSaveDirectory(fc.getSelectedFile());
            File file = fc.getSelectedFile();
            BytecodeViewer.updateBusyStatus(true);
            final String path = MiscUtils.append(file, ".java");
            if (!DialogUtils.canOverwriteFile(path))
                return;
            JOptionPane pane = new JOptionPane("What decompiler will you use?");
            Object[] options = new String[] { "All", "Procyon", "CFR", "Fernflower", "Krakatau", "Cancel" };
            pane.setOptions(options);
            JDialog dialog = pane.createDialog(BytecodeViewer.viewer, "Bytecode Viewer - Select Decompiler");
            dialog.setVisible(true);
            Object obj = pane.getValue();
            int result = -1;
            for (int k = 0; k < options.length; k++) if (options[k].equals(obj))
                result = k;
            if (result == 0) {
                Thread t1 = new Thread(() -> {
                    try {
                        final ClassWriter cw = new ClassWriter(0);
                        try {
                            Objects.requireNonNull(cn).accept(cw);
                        } catch (Exception e) {
                            e.printStackTrace();
                            try {
                                Thread.sleep(200);
                                Objects.requireNonNull(cn).accept(cw);
                            } catch (InterruptedException ignored) {
                            }
                        }
                        try {
                            DiskWriter.replaceFile(MiscUtils.append(file, "-procyon.java"), Decompiler.PROCYON_DECOMPILER.getDecompiler().decompileClassNode(cn, cw.toByteArray()), false);
                        } catch (Exception e) {
                            e.printStackTrace();
                        }
                        try {
                            DiskWriter.replaceFile(MiscUtils.append(file, "-CFR.java"), Decompiler.CFR_DECOMPILER.getDecompiler().decompileClassNode(cn, cw.toByteArray()), false);
                        } catch (Exception e) {
                            e.printStackTrace();
                        }
                        try {
                            DiskWriter.replaceFile(MiscUtils.append(file, "-fernflower.java"), Decompiler.FERNFLOWER_DECOMPILER.getDecompiler().decompileClassNode(cn, cw.toByteArray()), false);
                        } catch (Exception e) {
                            e.printStackTrace();
                        }
                        try {
