            j = 0;
            for (i = 0; i < numberOfNodes; i++) {
                if (Node_[i][3] != 0) {
                    // Restriction of the movement
                    NodeRestrict_[j][0] = i;
                    NodeRestrict_[j][1] = Node_[i][3];
                    j++;
                }
            }
